cards.extra:
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./control) || exit 1; for i in $I; do case $i in context|encoding/json|errors|fmt|net/http|time|unicode/utf8|morphstudio/queue|morphstudio/github|morphstudio/eventlog|morphstudio/session|morphstudio/stream) ;; *) echo "imports: package control imports $i (allowed: context, encoding/json, errors, fmt, net/http, time, unicode/utf8, morphstudio/queue, morphstudio/github, morphstudio/eventlog, morphstudio/session, morphstudio/stream)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' control/adopt.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' control/adopt.go 2>&1); [ -z "$C" ] || { echo "clock: control/adopt.go reads time.Now or time.Since (the clock is the now argument)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head; do C=$(gofmt -l -r "$x -> http.NoBody" control/adopt.go 2>&1); [ -z "$C" ] || { echo "net: control/adopt.go uses $x (no HTTP client and never a listener in package control)"; exit 1; }; done

